#define ALT_USB_HOST_HCDMA4_HCDMA4_SET_MSK    0xffffffff
/* The mask used to clear the ALT_USB_HOST_HCDMA4_HCDMA4 register field value. */
#define ALT_USB_HOST_HCDMA4_HCDMA4_CLR_MSK    0x00000000
